}

const cleanParams = {};
for (const [key, val] of Object.entries(rawParams)) {
  if (val === null || val === undefined || val === '' || val === 'null') continue;
  const expectedType = schema.types[key];
  let cleanVal = val;
  if (expectedType === 'number') {
    cleanVal = Number(val);
    if (isNaN(cleanVal)) continue;
  } else if (expectedType === 'string') {
    cleanVal = String(val).trim().replace(/[';]|--/g, ''); // SQL injection guard
    if (cleanVal === '') continue;
  }
  if (key === '@MaKhachHang') cleanVal = String(cleanVal).replace(/\s+/g,'').toUpperCase();
  cleanParams[key] = cleanVal;
}
if (!cleanParams['@Username'] && rawParams['@Username']) {
  cleanParams['@Username'] = rawParams['@Username'];
}
if (apiCode === '@tuyen_ban_hang') {
  const targetDate = rawParams['@NgayTarget'] || rawParams['@TuNgay'] || rawParams['@DenNgay'];
  if (targetDate) {
    cleanParams['@NgayTarget'] = String(targetDate).trim().replace(/[';]|--/g, '');
  }
}
if (apiCode === '@danh_muc') {
  if (!cleanParams['@timkiem']) {
    cleanParams['@timkiem'] = rawParams['@timkiem'] || rawParams['@EmployeeID'] || rawParams['@MaKhachHang'] || '';
  }
}

const tzOffset = (new Date()).getTimezoneOffset() * 60000; const todayStr = new Date(Date.now() - tzOffset).toISOString().split('T')[0]; if (apiCode === '@cong_no_khach_hang' || apiCode === '@cong_no_chi_tiet') { if (!cleanParams['@DenNgay']) cleanParams['@DenNgay'] = todayStr; } if (apiCode === '@doanh_so' || apiCode === '@hoa_don') { if (!cleanParams['@DenNgay']) cleanParams['@DenNgay'] = todayStr; if (!cleanParams['@TuNgay']) { const d = new Date(); const firstDay = new Date(d.getFullYear(), d.getMonth(), 1); cleanParams['@TuNgay'] = new Date(firstDay.getTime() - tzOffset).toISOString().split('T')[0]; } } const errors = [];

// Rule 1: TuNgay phải <= DenNgay
if (cleanParams['@TuNgay'] && cleanParams['@DenNgay']) {
  const tu = new Date(cleanParams['@TuNgay']);
  const den = new Date(cleanParams['@DenNgay']);
  if (tu > den) {
    errors.push(`Từ ngày (${cleanParams['@TuNgay']}) phải nhỏ hơn hoặc bằng Đến ngày (${cleanParams['@DenNgay']})`);
  }
}

// Rule 2: Khoảng ngày không quá 2 năm (tránh query nặng)
if (cleanParams['@TuNgay'] && cleanParams['@DenNgay']) {
  const diffDays = (new Date(cleanParams['@DenNgay']) - new Date(cleanParams['@TuNgay'])) / 86400000;
  if (diffDays > 730) {
    errors.push('Khoảng thời gian tra cứu không nên vượt quá 2 năm, anh/chị có thể thu hẹp lại không ạ?');
  }
}

// Rule 3: TopN hợp lý (1–100)
if (cleanParams['@TopN'] !== undefined) {
  if (cleanParams['@TopN'] < 1 || cleanParams['@TopN'] > 100) {
    cleanParams['@TopN'] = Math.min(Math.max(cleanParams['@TopN'], 1), 100); // Auto-clamp thay vì báo lỗi
  }
}

// Rule 4: timkiem tối thiểu 2 ký tự
if (cleanParams['@timkiem'] !== undefined && String(cleanParams['@timkiem']).length < 2) {
  errors.push('Từ khóa tìm kiếm cần ít nhất 2 ký tự ạ!');
}

if (errors.length > 0) {
  return [{ json: { isValid: false, cleanParams: {}, errorMsg: errors[0], validationLevel: 'BUSINESS' } }];
}

return [{ json: { isValid: true, cleanParams, errorMsg: null, validationLevel: 'PASSED' } }];

